function getGameplayDanceBranchCount(characterId){
  let count=0;

  teamCharacters.forEach(c=>{
    if(c?.id!==characterId)return;

    const rank=Math.max(
      1,
      Math.min(
        5,
        Number(user?.characterProgress?.[c.id]?.rank)||1
      )
    );

    count=Math.max(
      count,
      rank>=5?6:rank
    );
  });

  return count;
}

const shihoBranches=getGameplayDanceBranchCount('shiho');
const neneBranches=getGameplayDanceBranchCount('nene');
const hasNightAn=teamCharacters.some(c=>c?.id==='ns_an');

function extendActiveRhythmEffects(seconds){
  const add=Math.max(0,Number(seconds)||0),now=currentTime();
  if(scoreBoostUntil>now)scoreBoostUntil+=add;
  if(noMissUntil>now)noMissUntil+=add;
  if(trickUntil>now)trickUntil+=add;
  if(starlightUntil>now)starlightUntil+=add;
  if(shihoFeverUntil>now)shihoFeverUntil+=add;
  if(neneOverrideUntil>now)neneOverrideUntil+=add;
}

function dancePerfectForceActive(t){
  return (
    (shihoBranches>=6&&t<shihoFeverUntil) ||
    (neneBranches>=6&&t<neneOverrideUntil)
  );
}

