function activateCardSkill(index,t){
  const card=teamCards[index];
  if(!card)return;
  const skill=CARD_SKILLS[card.name];
  if(!skill){
    toast(`${card.name} · CARD SKILL`,'Card effect activated.',false);
    return;
  }

  const rank=Math.max(1,Math.min(5,Number(card.rank)||1));
  const duration=skill.durationByRank?.[rank] || skill.duration || 0;

  if(skill.type==='score'){
    scoreBoostValue=Math.max(scoreBoostValue,skill.boost||0);
    scoreBoostUntil=Math.max(scoreBoostUntil,t+duration);
    toast(`${card.name} · ${skill.name}`,`Score +${Math.round((skill.boost||0)*100)}% for ${duration}s`,false);
  }else if(skill.type==='hybrid'){
    scoreBoostValue=Math.max(scoreBoostValue,skill.boost||0);
    scoreBoostUntil=Math.max(scoreBoostUntil,t+duration);
    noMissUntil=Math.max(noMissUntil,t+(skill.guardDuration||4));
    toast(`${card.name} · ${skill.name}`,`Score +${Math.round((skill.boost||0)*100)}% for ${duration}s · NO MISS ${skill.guardDuration||4}s`,false);
  }else if(skill.type==='noMiss'){
    noMissUntil=Math.max(noMissUntil,t+duration);
    toast(`${card.name} · ${skill.name}`,`MISS protection for ${duration}s`,false);
  }
}

function activatePairSkill(index,t){
  skillActivationCount++;
  activateCharacterSkill(index,t);
  activateCardSkill(index,t);
  const c=teamCharacters[index];
  const card=teamCards[index];

  if(c?.id!=='ns_an' && t<anRelayUntil){
    const relay=c?.id==='ns_akito'?.45:.25;
    scoreBoostValue=Math.max(scoreBoostValue,relay);
    scoreBoostUntil=Math.max(scoreBoostUntil,t+(c?.id==='ns_akito'?10:8));
    toast('AN · BLUE RELAY',`${c?.name||'ALLY'} receives +${Math.round(relay*100)}% support.`,true);
  }

  if(c?.id!=='ns_saki' && t<sakiEffectFieldUntil){
    extendActiveRhythmEffects(2.5);
    toast('SAKI · EFFECT PARADE','New Character/Card effects extended +2.5s.',true);
  }

  skillLog.push(`SLOT ${index+1}: ${c?.name||'—'} + ${card?.name||'NO CARD'}`);
  document.querySelectorAll('.character-target').forEach((el,i)=>{
    el.classList.toggle('skill-ready',i===index);
  });
  setTimeout(()=>document.querySelectorAll('.character-target').forEach(el=>el.classList.remove('skill-ready')),700);
}

function shouldFinishFromAudio(t){
  if(!audio || !running || paused) return false;

  const duration=Number(audio.duration||0);
  if(audio.ended) return true;

  // Android WebView can occasionally skip the "ended" event.
  if(Number.isFinite(duration) && duration>0 && t>=duration-.08) return true;

  return false;
}

function loop(){
  if(!running||paused||!audio)return;
  const t=audio.currentTime;
  const hitCenter=getTargetCenterY();
  const noteSize=getNoteSize();
  const spawnCenter=-noteSize*.65;

  for(const note of notes){
    if(!note.el&&!note.hit&&!note.missed&&t>=note.time-travel)createNote(note);
    if(!note.el||note.hit||note.missed)continue;

    if(note.type==='hold'&&note.holding){
      const end=note.time+Number(note.duration||0);
      const remain=Math.max(0,end-t);
      const full=Math.max(noteSize*1.7,Number(note.visualHeight||noteSize*1.7));
      const h=Math.max(5,full*(remain/Math.max(.01,Number(note.duration||.7))));
      note.el.style.setProperty('--hold-height',`${h}px`);
      note.el.style.transform=`translate3d(-50%,${hitCenter-h}px,0)`;
      note.el.classList.add('holding');

      if(t>=end-.02){
        if(lanePressed[note.lane]||isNoMissActive(t))finishHold(note,t);
        else handleMiss(note,t);
      }
      continue;
    }

    const diff=note.time-t;
    const progress=1-diff/travel;
    const centerY=spawnCenter+(hitCenter-spawnCenter)*progress;

    if(note.type==='hold'){
      const h=Number(note.visualHeight||noteSize*1.7);
      note.el.style.transform=`translate3d(-50%,${centerY-h}px,0)`;
    }else{
      note.el.style.transform=`translate3d(-50%,${centerY-noteSize/2}px,0)`;
    }

    if(diff<-hitWindow)handleMiss(note,t);
  }

  if(shouldFinishFromAudio(t)){
    showResult(false);
    return;
  }

  frame=requestAnimationFrame(loop);
}

function hit(lane){
  if(!running||paused||!audio)return;
  const t=audio.currentTime;
  let target=null,closest=Infinity;

  for(const note of notes){
    if(note.hit||note.missed||note.lane!==lane)continue;
    const diff=Math.abs(note.time-t);
    if(diff<=hitWindow&&diff<closest){closest=diff;target=note}
  }
  if(!target)return;

  if(target.type==='hold'){
    target.holding=true;
    target.holdStartedAt=t;
    target.holdJudgement=
      (dancePerfectForceActive(t)||shihoBranches>=2)
        ?'PERFECT'
        :(neneBranches>=2
            ?(closest<=greatWindow?'PERFECT':'GREAT')
            :(closest<=perfectWindow?'PERFECT':closest<=greatWindow?'GREAT':'OKAY'));
    target.el?.classList.add('holding');
    judge(`HOLD ${target.holdJudgement}`);
    return;
  }

  target.hit=true;
  combo++;
  maxCombo=Math.max(maxCombo,combo);

  if(target.type==='skill'){
    score+=scaledScore(500,t,'PERFECT');
    perfect++;
    activatePairSkill(lane,t);
    judge('SKILL!');
  }else if(dancePerfectForceActive(t)||shihoBranches>=2||closest<=perfectWindow){
    score+=scaledScore(1000,t,'PERFECT');
    perfect++;
    judge((dancePerfectForceActive(t)||shihoBranches>=2)?'DANCE PERFECT':'PERFECT');
  }else if(neneBranches>=2){
    if(closest<=greatWindow){
      score+=scaledScore(1000,t,'PERFECT');
      perfect++;
      judge('NENE PERFECT');
    }else{
      score+=scaledScore(700,t,'GREAT');
      great++;
      judge('NENE PATCH · GREAT');
    }
  }else if(closest<=greatWindow){
    score+=scaledScore(700,t,'GREAT');great++;judge('GREAT');
  }else{
    score+=scaledScore(400,t,'OKAY');okay++;judge('OKAY');
  }

  updateDanceComboPassives(t);
  removeNote(target,true);
  hud();
}

function setPaused(value){
  if(!running||!audio)return;
  paused=value;
  $('pauseOverlay').classList.toggle('hidden',!paused);
  if(paused){
    lanePressed.fill(false);
    pointerLaneMap.clear();
    document.querySelectorAll('.character-target').forEach(el=>el.classList.remove('active'));
    audio.pause();
    cancelAnimationFrame(frame);
  }else{
    audio.play().catch(()=>{});
    syncVisualViewport();
    frame=requestAnimationFrame(loop);
  }
}


